import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
let mode = args[0]
let workers = 0
if ((mode === 'waves' || mode === 'explain') && args.length === 1) {
  // ok
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)

const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const NAME = /^[A-Za-z0-9_.-]+$/
const cost = new Map()
const deps = new Map()
const refs = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) if (!NAME.test(x)) fail(`error: line ${n}: invalid task name ${x}`)
    refs.push(...w.slice(1))
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const r of refs) if (!cost.has(r)) fail(`error: unknown task ${r}`)

const names = [...cost.keys()].sort()
const dl = new Map(names.map((t) => [t, [...(deps.get(t) ?? [])].sort()]))

// cycle detection
const state = new Map()
const stack = []
function dfs(t) {
  state.set(t, 1)
  stack.push(t)
  for (const d of dl.get(t)) {
    if (state.get(d) === 1) {
      const cyc = stack.slice(stack.indexOf(d)).concat(d)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!state.has(d)) dfs(d)
  }
  stack.pop()
  state.set(t, 2)
}
for (const t of names) if (!state.has(t)) dfs(t)

const start = new Map()
const depth = new Map()
function calc(t) {
  if (depth.has(t)) return
  let s = 0
  let dp = 0
  for (const d of dl.get(t)) {
    calc(d)
    s = Math.max(s, start.get(d) + cost.get(d))
    dp = Math.max(dp, depth.get(d) + 1)
  }
  start.set(t, s)
  depth.set(t, dp)
}
names.forEach(calc)
let total = 0
for (const t of names) total = Math.max(total, start.get(t) + cost.get(t))

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const t of names) (ws[depth.get(t)] ??= []).push(t)
  ws.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const t of names) out += `${t} start=${start.get(t)} finish=${start.get(t) + cost.get(t)} depth=${depth.get(t)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((t) => [t, []]))
  for (const t of names) for (const d of dl.get(t)) rev.get(d).push(t)
  const prio = new Map()
  const pr = (t) => {
    if (prio.has(t)) return prio.get(t)
    let m = 0
    for (const u of rev.get(t)) m = Math.max(m, pr(u))
    prio.set(t, m + cost.get(t))
    return m + cost.get(t)
  }
  names.forEach(pr)
  const fin = new Map()
  const freeAt = Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0
  let left = names.length
  let makespan = 0
  while (left > 0) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let best = null
      for (const x of names) {
        if (fin.has(x)) continue
        if (!dl.get(x).every((d) => fin.has(d) && fin.get(d) <= t)) continue
        if (best === null || prio.get(x) > prio.get(best)) best = x
      }
      if (best === null) break
      const f = t + cost.get(best)
      fin.set(best, f)
      freeAt[w] = f
      runs[w].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
      left--
    }
    if (left === 0) break
    const nxt = [...freeAt, ...fin.values()].filter((f) => f > t)
    t = Math.min(...nxt)
  }
  runs.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
node --test test/*.test.js 2>&1 | tail -8","description":"Write CLI and run tests"}

