  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

function validate(r) {
  const comps = []
  comps.push(['path', r.path])
  let a
  if (r.authority !== undefined) {
    a = splitAuthority(r.authority)
    comps.push(['userinfo', a.userinfo ?? ''], ['host', a.host])
  }
  comps.push(['query', r.query ?? ''], ['fragment', r.fragment ?? ''])
  for (const [n, v] of comps) {
    if (checkPct(v)) throw new ParseError(`the ${n} has a truncated percent-encoding`)
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(r) {
  validate(r)
  const scheme = r.scheme === undefined ? undefined : lower(r.scheme)
  let authority
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    let s = ''
    if (a.userinfo !== undefined) s += pct(a.userinfo) + '@'
    s += lower(pct(a.host))
    if (a.port !== undefined) {
      const port = pct(a.port)
      if (port !== '' && port !== DEFAULT_PORTS[scheme]) s += ':' + port
    }
    authority = s
  }
  let path = removeDots(pct(r.path))
  if (authority !== undefined && path === '') path = '/'
  let o = ''
  if (scheme !== undefined) o += scheme + ':'
  if (authority !== undefined) o += '//' + authority
  o += path
  if (r.query !== undefined) o += '?' + pct(r.query)
  if (r.fragment !== undefined) o += '#' + pct(r.fragment)
  return o
}

export function resolve(line) {
  const sp = line.indexOf(' ')
  if (sp < 0) throw new ParseError('expected a base and a reference')
  const base = parse(line.slice(0, sp))
  const ref = parse(line.slice(sp + 1))
  if (base.scheme === undefined) throw new ParseError('the base has no scheme')
  let t
  if (ref.scheme !== undefined) t = { ...ref }
  else if (ref.authority !== undefined) t = { ...ref, scheme: base.scheme }
  else if (ref.path === '') {
    t = { scheme: base.scheme, authority: base.authority, path: base.path,
      query: ref.query !== undefined ? ref.query : base.query, fragment: ref.fragment }
  } else {
    let path
    if (ref.path.startsWith('/')) path = ref.path
    else if (base.authority !== undefined && base.path === '') path = '/' + ref.path
    else {
      const i = base.path.lastIndexOf('/')
      path = base.path.slice(0, i + 1) + ref.path
    }
    t = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }
  return normalize(t)
}
