import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) fail('usage: cli.js merge|merge2|regions')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) fail('expected three parts separated by %%%')
const [mine, base, theirs] = docs

function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = (bi, sj) => {
    if (bi > bs || sj > ss) out.push({ bs, be: bi, ss, se: sj, who })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++; j++; bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  flush(n, m)
  return out
}

const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
all.sort((a, b) => a.bs - b.bs || a.who - b.who)

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])
const out = []
const reg = []
let pos = 0
let k = 0
while (k < all.length) {
  const first = all[k]
  const rs = first.bs
  let re = first.be
  const group = [first]
  k++
  while (k < all.length && all[k].bs <= re) {
    re = Math.max(re, all[k].be)
    group.push(all[k++])
  }
  if (rs > pos) {
    out.push(...base.slice(pos, rs))
    reg.push(`stable ${rs - pos}`)
  }
  const baseL = base.slice(rs, re)
  const side = (doc, who) => {
    const g = group.filter(c => c.who === who)
    if (!g.length) return baseL
    const minBs = Math.min(...g.map(c => c.bs)), maxBe = Math.max(...g.map(c => c.be))
    const s = Math.min(...g.map(c => c.ss)) - (minBs - rs)
    const e = Math.max(...g.map(c => c.se)) + (re - maxBe)
    return doc.slice(s, e)
  }
  const m = side(mine, 0), t = side(theirs, 1)
  if (eq(m, t)) { out.push(...m); reg.push(`both ${m.length}`) }
  else if (eq(m, baseL)) { out.push(...t); reg.push(`theirs ${t.length}`) }
  else if (eq(t, baseL)) { out.push(...m); reg.push(`mine ${m.length}`) }
  else {
    conflict = true
    out.push('<<<<<<< mine', ...m)
    if (mode === 'merge') out.push('||||||| base', ...baseL)
    out.push('=======', ...t, '>>>>>>> theirs')
    reg.push(`conflict mine=${m.length} base=${baseL.length} theirs=${t.length}`)
  }
  pos = re
}
if (pos < base.length) {
  out.push(...base.slice(pos))
  reg.push(`stable ${base.length - pos}`)
}
var conflict
const res = mode === 'regions' ? reg : out
process.stdout.write(res.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
EOF
