{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { buildEvaluator, depsOf, formatValue, parseFormula } from './formula.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')
const parsed = parseSheet(input)
if (parsed.error) {
  process.stderr.write(parsed.error + '\n')
  process.exit(2)
}

const cells = parsed.cells // sorted array of {addr, col, row, content}
let out = ''
if (mode === 'values') {
  const ev = buildEvaluator(cells)
  for (const c of cells) out += `${c.addr}=${formatValue(ev.valueOf(c.addr))}\n`
} else {
  for (const c of cells) {
    let names = []
    if (c.content.startsWith('=')) {
      const p = parseFormula(c.content.slice(1))
      if (p.ok) names = depsOf(p)
    }
    out += `${c.addr}:${names.map((n) => ' ' + n).join('')}\n`
  }
}
process.stdout.write(out)
"}

{"file_path":"src/sheet.js","content":"export function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const letters = m[1].toUpperCase()
  const col = letters.length === 1 ? letters.charCodeAt(0) - 64 : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
  return { col, row, addr: letters + row, letters }
}

export function colName(col) {
  if (col <= 26) return String.fromCharCode(64 + col)
  const k = col - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

export function addrOf(col, row) {
  return colName(col) + row
}

export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const seen = new Map()
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].replace(/^[ \t]+/, '')
    if (t === '' || t[0] === '#') continue
    let j = 0
    while (j < t.length && t[j] !== ' ' && t[j] !== '\t') j++
    const raw = t.slice(0, j)
    let k = j
    while (k < t.length && (t[k] === ' ' || t[k] === '\t')) k++
    const content = t.slice(k)
    const a = parseAddr(raw)
    if (!a) return { error: `error: line ${i + 1}: invalid cell address ${raw}` }
    if (seen.has(a.addr)) return { error: `error: line ${i + 1}: cell ${a.addr} is declared twice` }
    seen.set(a.addr, { addr: a.addr, col: a.col, row: a.row, content })
  }
  const cells = [...seen.values()].sort((x, y) => x.col - y.col || x.row - y.row)
  return { cells }
}
"}

{"file_path":"src/formula.js","content":"import { parseAddr, addrOf } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ k: 'num', v })
const err = (v) => ({ k: 'err', v })

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[<>=+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

class Fail extends Error {}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return { ok: false }
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Fail() }
  const expect = (v) => { if (!isOp(v)) fail(); p++ }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) fail()
    if (tk.t === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.t === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      expect(')')
      return { t: 'group', e }
    }
    if (tk.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            expect(')')
            break
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
