      while (isIdent(cs[i])) adv()
      const w = cs.slice(start, i).join('')
      tokens.push([sl, sc, KEYWORDS.has(w) ? 'keyword' : 'ident', w])
      continue
    }
    if (isDigit(c)) {
      const run = (pred) => {
        // digits with single underscores between digits
        let any = false
        while (i < n) {
          if (pred(cs[i])) { adv(); any = true }
          else if (cs[i] === '_' && any && pred(cs[i - 1]) && pred(cs[i + 1])) adv()
          else break
        }
        return any
      }
      let ok = true
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        adv(); adv()
        const l = p.toLowerCase()
        const pred = l === 'x' ? isHex : l === 'b' ? (d) => d === '0' || d === '1' : (d) => d >= '0' && d <= '7' && d.length === 1
        ok = run(pred)
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { adv(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
