          if (cp > 0x10ffff) bad()
          v += String.fromCodePoint(cp)
          while (i <= j) adv()
        } else bad()
      }
      tokens.push([sl, sc, 'string', JSON.stringify(v)])
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.includes(two)) { adv(); adv(); tokens.push([sl, sc, 'punct', two]); continue }
    if (PUNCT1.includes(c)) { adv(); tokens.push([sl, sc, 'punct', c]); continue }
    fail(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
