try {
  toks = scan(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'tokens') {
  for (const [l, c, k, b] of toks) out += `${l}:${c} ${k} ${b}\n`
} else {
  const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
  for (const t of toks) counts[t[2]]++
  for (const k of Object.keys(counts)) out += `${k} ${counts[k]}\n`
  out += `total ${toks.length}\n`
}
