function advance(p, st, tick) {
  if (p.kind === 'bucket') {
    if (st.last === null) { st.num = p.cap * p.per; st.last = tick; return }
    const n = tick - st.last
    st.last = tick
    st.num += p.refill * n
    const max = p.cap * p.per
    if (st.num > max) st.num = max
