const routes = new Map()
const out = []
const stats = new Map()
let started = false
let lastTick = null

function int(v, field, least) {
  if (!UINT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function advance(p, st, tick) {
  if (p.kind === 'bucket') {
    if (st.last === null) { st.num = p.cap * p.per; st.last = tick; return }
    const n = tick - st.last
    st.last = tick
    st.num += p.refill * n
    const max = p.cap * p.per
    if (st.num > max) st.num = max
  } else {
    const cut = tick - p.span
    st.ticks = st.ticks.filter((t) => t > cut)
  }
}
const allows = (p, st) => (p.kind === 'bucket' ? st.num >= p.per : BigInt(st.ticks.length) < p.limit)
function record(p, st, tick) {
  if (p.kind === 'bucket') st.num -= p.per
  else st.ticks.push(tick)
}

